20	PAGE = '''<!doctype html>
21	<html lang="zh-CN">
22	<head>
23	<meta charset="utf-8">
24	<meta name="viewport" content="width=device-width,initial-scale=1">
25	<title>ClientBook · 客户联系人与商机记录</title>
26	<style>
27	body{font-family:system-ui,sans-serif;max-width:60rem;margin:3rem auto;padding:0 1rem;line-height:1.7;color:#1c2733}
28	a{color:#175b9c}
29	h1{margin-bottom:.2rem}
30	.subtitle{color:#5b6b7b;margin-top:0}
31	.card{border:1px solid #d8dee6;border-radius:8px;padding:1rem 1.25rem;margin:1.5rem 0}
32	.card h2{margin-top:0;font-size:1.15rem}
33	.filename{margin-left:.5rem;color:#5b6b7b}
34	button{font-size:1rem;padding:.45rem 1.4rem;border-radius:6px;border:1px solid #175b9c;background:#175b9c;color:#fff;cursor:pointer}
35	button:disabled{background:#9db6cc;border-color:#9db6cc;cursor:default}
36	.hint{color:#5b6b7b;font-size:.9rem;margin:.35rem 0 0}
37	#report{display:none;margin-top:1rem}
38	.banner{padding:.6rem 1rem;border-radius:6px;margin-bottom:.75rem}
39	.banner.ok{background:#e9f7ec;border:1px solid #bfe3c8}
40	.banner.bad{background:#fdeeee;border:1px solid #f3c4c4}
41	.banner.warn{background:#fdf6e6;border:1px solid #ecd9a8}
42	.banner.busy{background:#eef4fb;border:1px solid #c3d5e8}
43	.failures{border:1px solid #ecd7d7;background:#fdf6f6;border-radius:6px;padding:.5rem 1rem;max-height:16rem;overflow:auto}
44	.failures b{color:#a02b2b}
45	.failures ul{margin:.4rem 0}
46	table{border-collapse:collapse;width:100%}
47	#clients-table{display:none}
48	#clients-table.on{display:table}
49	#clients-empty{display:none}
50	#clients-empty.on{display:block}
51	#clients-load-error{display:none}
52	#clients-load-error.on{display:block;color:#a06a16}
53	th,td{text-align:left;padding:.45rem .6rem;border-bottom:1px solid #e3e8ee;vertical-align:top}
54	th{font-size:.85rem;color:#5b6b7b;font-weight:600}
55	.muted{color:#9aa7b4}
56	#clients-body tr.selected{background:#f1f6fb}
57	.sel-panel{background:#f5f8fb;border:1px solid #d8dee6;border-radius:6px;padding:.6rem .8rem;margin:.8rem 0}
58	.sel-list{margin-top:.35rem}
59	.sel-chip{display:inline-block;background:#fff;border:1px solid #cdd7e2;border-radius:999px;padding:.1rem .35rem .1rem .6rem;margin:.2rem .35rem .2rem 0;font-size:.9rem;white-space:nowrap}
60	.sel-chip button{border:none;background:none;color:#5b6b7b;font-size:1.05rem;line-height:1;padding:0 .25rem;cursor:pointer}
61	.sel-chip button:hover{color:#a02b2b}
62	.bf{border:1px solid #d8dee6;border-radius:6px;padding:.55rem .8rem;margin:.6rem 0}
63	.bf-head{display:flex;flex-wrap:wrap;gap:.8rem;align-items:center;margin-bottom:.35rem}
64	.bf-head b{min-width:4.5rem}
65	.bf-head label{font-weight:400;white-space:nowrap}
66	.bf textarea{width:100%;box-sizing:border-box;font:inherit;resize:vertical;padding:.3rem .45rem}
67	.bf input[type=text]{font:inherit;padding:.3rem .45rem}
68	.bf textarea:disabled,.bf input:disabled{background:#f2f4f7;color:#8a97a5}
69	.bf .val-hint{margin:.25rem 0 0;font-size:.85rem;color:#5b6b7b}
70	#batch-report{margin-top:.75rem}
71	.footer{color:#5b6b7b;font-size:.9rem;margin-top:2rem}
72	</style>
73	</head>
74	<body>
75	<main>
76	<h1>ClientBook</h1>
77	<p class="subtitle">客户联系人与商机记录</p>
78	
79	<section class="card">
80	<h2>从 CSV 导入客户</h2>
81	<form id="import-form">
82	  <!-- 不使用原生 required 拦截：未选文件时由提交处理统一在页内提示先选择 CSV，
83	       与批量修改表单的自定义校验提示口径一致，避免原生气泡拦截后页内无提示。 -->
84	  <input type="file" id="file-input" accept=".csv,text/csv,text/plain">
85	  <span class="filename" id="filename"></span>
86	  <div style="margin-top:.75rem"><button type="submit" id="submit-btn">导入</button></div>
87	</form>
88	<p class="hint">表头须包含 name（必需），可选 source、region、industry、important_date，顺序不限；重要日期须为 YYYY-MM-DD 真实日期。支持带引号字段与字段内换行（UTF-8，可带 BOM）。</p>
89	<div id="report"></div>
90	</section>
91	
92	<h2>客户列表</h2>
93	<p id="clients-empty" class="muted">还没有客户记录。</p>
94	<p id="clients-load-error" class="muted"></p>
95	<table id="clients-table">
96	  <thead><tr><th style="width:2.2rem"><input type="checkbox" id="check-all" title="全选/取消全选当前列表"></th><th>编号</th><th>客户名称</th><th>来源</th><th>地区</th><th>行业</th><th>重要日期</th></tr></thead>
97	  <tbody id="clients-body"></tbody>
98	</table>
99	
100	<section class="card" id="batch-card">
101	<h2>批量修改选中客户</h2>
102	<div class="sel-panel">
103	  已选择 <b id="sel-count">0</b> 名客户：
104	  <div class="sel-list" id="sel-list"><span class="muted" id="sel-none">尚未勾选任何客户，勾选列表中的客户后可批量修改。</span></div>
105	</div>
106	<form id="batch-form">
107	  <div id="batch-fields"></div>
108	  <p class="hint">每个字段可分别选择「保持原值」「设为填写的值」或「清空」；初次进入编辑时全部保持原值，留空不会清空资料。来源、地区和行业保留内部空白与换行，仅含空白的填写值按清空处理；重要日期须为 YYYY-MM-DD 真实日历日期。客户名称和编号不参与编辑，也不会新建客户。</p>
109	  <div style="margin-top:.6rem">
110	    <button type="submit" id="batch-submit" disabled>保存修改</button>
111	  </div>
112	</form>
113	<div id="batch-report"></div>
114	</section>
115	
116	<p class="footer"><a href="/api/clients">查看客户列表接口</a> · <a href="/health">服务状态</a></p>
117	</main>
118	<script>
119	const ESC = {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"};
120	const esc = s => String(s === null || s === undefined ? "" : s).replace(/[&<>"']/g, c => ESC[c]);
121	const blank = v => (v === null || v === undefined || v === "") ? '<span class="muted">—</span>' : esc(v);
122	
123	const BATCH_FIELDS = [
124	  {key: "source", label: "来源"},
125	  {key: "region", label: "地区"},
126	  {key: "industry", label: "行业"},
127	  {key: "important_date", label: "重要日期", date: true},
128	];
129	
130	let clients = [];
131	const selected = new Set();
132	// 一次批量保存从发出到本次结果处理结束期间为 true：期间只能有这一次请求，
133	// 勾选变化与表单重复提交都不能解除或新增请求。
134	let batchSaving = false;
135	// 一次 CSV 导入从提交文件开始，到回复读取、结果展示以及该结果需要的客户列表
136	// 刷新全部结束期间为 true：期间只能有最初发出的那一次导入请求；重复点击、
137	// 回车等再次触发表单提交都直接忽略，不解除等待、不新增请求、不更换提示。
138	let importing = false;
139	// 客户列表读取的发起序号，只增不减：同一页面可能同时有多次读取在途
140	// （首次打开、导入成功后、批量保存成功后都会各自发起一次）。先后以读取
141	// 发起的时间为准，而不是回复到达的时间：只有序号仍等于当前最新值的读取
142	// （即最近发起的那次）才能决定表格内容与读取提示；较早发起的读取无论
143	// 成功、失败还是空列表、无论回复何时到达，都不再影响页面——不能覆盖
144	// 更新读取已经显示的客户资料，不能新增读取失败或列表暂未更新的提示，
145	// 也不能撤掉更新读取已经给出的提示或换掉它保留的表格。
146	let loadSeq = 0;
147	
148	function syncSubmitState() {
149	  const btn = document.getElementById("batch-submit");
150	  btn.disabled = batchSaving || selected.size === 0;
151	  btn.textContent = batchSaving ? "正在保存…" : "保存修改";
152	}
153	
154	function syncImportState() {
155	  const btn = document.getElementById("submit-btn");
156	  btn.disabled = importing;
157	  btn.textContent = importing ? "正在导入…" : "导入";
158	}
159	
160	async function loadClients() {
161	  // 只在明确读到有效客户列表（真正的空列表也算）时才更新页面；
162	  // 连接错误、非成功状态、响应无法解析或未包含 clients 数组都视为读取失败：
163	  // 保留此前已显示的客户编号、名称与各字段内容，不清空表格、不显示空列表提示。
164	  // 返回 "updated"（本次是最近发起的读取且已更新页面）或 "stale"（已有更新的
165	  // 读取发起，本次结果不再影响页面）；最近发起的读取失败时抛错，由调用方
166	  // 补充各自场景的提示。
167	  const seq = ++loadSeq;
168	  const stale = () => seq !== loadSeq;
169	  const note = document.getElementById("clients-load-error");
170	  let list;
171	  try {
172	    const res = await fetch("/api/clients");
173	    if (!res.ok) throw new Error("服务返回非成功状态（HTTP " + res.status + "）");
174	    const data = await res.json();
175	    if (!data || !Array.isArray(data.clients)) {
176	      throw new Error("响应未包含有效的客户列表");
177	    }
178	    list = data.clients;
179	  } catch (err) {
180	    // 已有更新的读取发起：本次旧回复（包括连接错误、非成功状态、无法解析）
181	    // 不再影响页面，不新增读取失败提示，也不动表格与勾选。
182	    if (stale()) return "stale";
183	    let message = err.message;
184	    if (err instanceof SyntaxError) message = "响应无法解析为有效数据";
185	    if (err instanceof TypeError) message = "无法连接到服务（网络错误）";
186	    note.textContent = "客户列表读取失败：" + message +
187	      "，当前显示的资料可能不是最新内容；保存结果不受影响，稍后刷新页面即可重新读取。";
188	    note.classList.add("on");
189	    // 读取失败期间不能让表格或“还没有客户记录”冒充真实的空列表；
190	    // 此前已渲染的行保留不动，之后真正读到空列表时再由 renderClients 恢复空状态提示。
191	    document.getElementById("clients-empty").classList.remove("on");
192	    throw new Error(message);
193	  }
194	  // 等待回复期间已有更新的读取发起：本次旧列表（即使真实、即使是空列表）
195	  // 不能抢先决定页面内容，客户行、读取提示、现有勾选与已选客户说明都保持不动。
196	  if (stale()) return "stale";
197	  note.classList.remove("on");
198	  note.textContent = "";
199	  clients = list;
200	  const known = new Set(clients.map(r => r.id));
201	  for (const id of [...selected]) {
202	    if (!known.has(id)) selected.delete(id);
203	  }
204	  renderClients();
205	  renderSelection();
206	  return "updated";
207	}
208	
209	function renderClients() {
210	  const tbl = document.getElementById("clients-table");
211	  const empty = document.getElementById("clients-empty");
212	  const body = document.getElementById("clients-body");
213	  if (clients.length) {
214	    tbl.classList.add("on");
215	    empty.classList.remove("on");
216	    body.innerHTML = clients.map(r =>
217	      '<tr data-id="' + esc(r.id) + '"' + (selected.has(r.id) ? ' class="selected"' : "") + ">" +
218	      '<td><input type="checkbox" class="row-check" value="' + esc(r.id) + '"' +
219	      (selected.has(r.id) ? " checked" : "") + " aria-label='选择客户 " + esc(r.id) + "'></td>" +
220	      "<td>" + esc(r.id) + "</td><td>" + esc(r.name) + "</td><td>" + blank(r.source) +
221	      "</td><td>" + blank(r.region) + "</td><td>" + blank(r.industry) +
222	      "</td><td>" + blank(r.important_date) + "</td></tr>").join("");
223	  } else {
224	    tbl.classList.remove("on");
225	    empty.classList.add("on");
226	    body.innerHTML = "";
227	  }
228	  syncCheckAll();
229	}
230	
231	function syncCheckAll() {
232	  const box = document.getElementById("check-all");
233	  box.checked = clients.length > 0 && selected.size === clients.length;
234	  box.indeterminate = selected.size > 0 && selected.size < clients.length;
235	}
236	
237	function renderSelection() {
238	  document.getElementById("sel-count").textContent = String(selected.size);
239	  const list = document.getElementById("sel-list");
240	  if (!selected.size) {
241	    list.innerHTML = '<span class="muted">尚未勾选任何客户，勾选列表中的客户后可批量修改。</span>';
242	  } else {
243	    const byId = new Map(clients.map(r => [r.id, r]));
244	    list.innerHTML = [...selected].sort((a, b) => a - b).map(id => {
245	      const r = byId.get(id);
246	      return '<span class="sel-chip">#' + esc(id) + " " + esc(r ? r.name : "") +
247	        ' <button type="button" data-remove="' + esc(id) + '" title="取消勾选该客户">×</button></span>';
248	    }).join("");
249	  }
250	  syncSubmitState();
251	  document.querySelectorAll("#clients-body tr").forEach(tr => {
252	    tr.classList.toggle("selected", selected.has(Number(tr.dataset.id)));
253	  });
254	  syncCheckAll();
255	}
256	
257	function buildBatchFields() {
258	  const wrap = document.getElementById("batch-fields");
259	  wrap.innerHTML = BATCH_FIELDS.map(f =>
260	    '<div class="bf" data-field="' + f.key + '">' +
261	      '<div class="bf-head"><b>' + f.label + "</b>" +
262	        '<label><input type="radio" name="' + f.key + '-op" value="keep" checked> 保持原值</label>' +
263	        '<label><input type="radio" name="' + f.key + '-op" value="set"> 设为填写的值</label>' +
264	        '<label><input type="radio" name="' + f.key + '-op" value="clear"> 清空</label>' +
265	      "</div>" +
266	      (f.date
267	        ? '<input type="text" class="bf-value" disabled placeholder="YYYY-MM-DD" autocomplete="off">'
268	        : '<textarea class="bf-value" rows="2" disabled></textarea>') +
269	      '<p class="val-hint">' + (f.date
270	        ? "非空时须为 YYYY-MM-DD 真实日历日期；仅含空白的填写值按清空处理。"
271	        : "去除前后空白后保存，内部空白与换行保留；仅含空白的填写值按清空处理。") +
272	      "</p></div>").join("");
273	  wrap.querySelectorAll(".bf").forEach(card => {
274	    const input = card.querySelector(".bf-value");
275	    card.querySelectorAll('input[type=radio]').forEach(radio => radio.addEventListener("change", () => {
276	      const op = card.querySelector('input[type=radio]:checked').value;
277	      input.disabled = op !== "set";
278	      if (op === "set") input.focus();
279	    }));
280	  });
281	}
282	
283	function collectBatchPayload() {
284	  const updates = {};
285	  for (const card of document.querySelectorAll("#batch-fields .bf")) {
286	    const key = card.dataset.field;
287	    const op = card.querySelector('input[type=radio]:checked').value;
288	    if (op === "keep") {
289	      updates[key] = {op: "keep"};
290	    } else if (op === "clear") {
291	      updates[key] = {op: "clear"};
292	    } else {
293	      updates[key] = {op: "set", value: card.querySelector(".bf-value").value};
294	    }
295	  }
296	  return {ids: [...selected].sort((a, b) => a - b), updates};
297	}
298	
299	function resetBatchForm() {
300	  document.querySelectorAll("#batch-fields .bf").forEach(card => {
301	    card.querySelector('input[value=keep]').checked = true;
302	    const input = card.querySelector(".bf-value");
303	    input.value = "";
304	    input.disabled = true;
305	  });
306	}
307	
308	function showBatchReport(html) {
309	  document.getElementById("batch-report").innerHTML = html;
310	}
311	
312	// CSV 导入与批量修改共用的服务回复读取：先取回复原文，再尝试解析为 JSON。
313	// parsed 区分「回复确实解析成了 JSON」与「只是纯文本/空回复」：能解析成 JSON
314	// 却没有合格 error 或有效数量的回复，不能把整个结构当作说明或成功依据。
315	// 回复体读取失败时返回 null：此时不知道服务是否已经写入，调用方按无法确认处理。
316	async function readServiceReply(res) {
317	  let raw;
318	  try {
319	    raw = await res.text();
320	  } catch (readErr) {
321	    return null;
322	  }
323	  let data = null;
324	  let parsed = false;
325	  if (raw.trim()) {
326	    try {
327	      data = JSON.parse(raw);
328	      parsed = true;
329	    } catch {
330	      data = null;
331	      parsed = false;
332	    }
333	  }
334	  return {raw, data, parsed};
335	}
336	
337	// CSV 导入与批量修改共用的可读原因识别：回复成功解析为 JSON 时，只取对象中的
338	// 非空文本 error；只有回复不是 JSON 结构化数据时，才把纯文本原文（去首尾空白，
339	// 最多前 200 个字符）当作原因。能解析成 JSON 却没有合格 error 的回复
340	// （如 {"message":"..."}、null、[]、字符串形式的 JSON），或 error 只有空白、
341	// 不是文本，都不算可读原因，不向用户倾倒结构；空回复同样返回空串。
342	// trimJsonReason 只控制 JSON error 的呈现方式：导入去掉首尾空白，批量修改保留原文。
343	function serviceReadableError(parsed, data, raw, trimJsonReason) {
344	  if (parsed) {
345	    if (data && typeof data === "object" && !Array.isArray(data) &&
346	        typeof data.error === "string") {
347	      const reason = trimJsonReason ? data.error.trim() : data.error;
348	      if (reason.trim()) return reason;
349	    }
350	    return "";
351	  }
352	  return (raw || "").trim().slice(0, 200);
353	}
354	
355	// CSV 导入与批量修改共用的非成功回复判定（reply 为 readServiceReply 的结果）：
356	// 只有 HTTP 400 且取得可读原因时，才能确认整次操作被服务明确拒绝
357	// （outcome 为 "rejected"，reason 即可读原因，trimJsonReason 按各自口径决定
358	// JSON 原因的呈现方式）；HTTP 400 没有可靠原因、HTTP 500/502 等其他非成功
359	// 状态（即使带有可解析的错误说明）都按无法确认处理（outcome 为 "unconfirmed"，
360	// detail 保留可读的说明、没有则为空串）。具体提示措辞由调用方按各自场景组织：
361	// 不显示成功数量，不断言客户资料未变或已经回滚。
362	function classifyFailureReply(res, reply, trimJsonReason) {
363	  const detail = serviceReadableError(reply.parsed, reply.data, reply.raw, trimJsonReason);
364	  if (res.status === 400 && detail) {
365	    return {outcome: "rejected", reason: detail};
366	  }
367	  return {outcome: "unconfirmed", status: res.status, detail};
368	}
369	
370	// 没有取得可靠保存结论时的统一口径（非 400 错误、400 无可读原因、连接中断、
371	// 回复无法读取/解析、成功状态却没有有效处理数量）：不显示成功数量，不断言
372	// 客户资料一定未变或已经回滚，也不按旧表格内容推算本次是否成功；请用户先
373	// 核对客户列表再主动决定是否重新保存。勾选、字段操作与已填内容全部保留，
374	// 不执行保存成功后的清理，也不自动再次发送修改。
375	function unconfirmedBatchHtml(prefix) {
376	  return '<div class="banner bad">' + prefix +
377	    "本次修改是否生效暂时无法确认，客户资料可能已经改变，不能视为全部未修改或已经回滚；" +
378	    "请先核对客户列表，再决定是否重新保存。当前勾选、字段操作与已填内容均已保留，" +
379	    "不会自动重新提交。</div>";
380	}
