405	document.getElementById("batch-form").addEventListener("submit", async e => {
406	  e.preventDefault();
407	  // 等待结果期间再次提交（重复点击、回车等）一律忽略：不增加请求、不提前显示成功、
408	  // 不清除已填内容；等待期间的勾选变化也不会在结果返回后自动补交。
409	  if (batchSaving) return;
410	  if (!selected.size) {
411	    showBatchReport('<div class="banner bad">请先勾选至少一名客户。</div>');
412	    syncSubmitState();
413	    return;
414	  }
415	  // 以本次点击时的勾选与填写为准，固化请求内容；等待期间勾选变化不影响本次请求。
416	  const payload = collectBatchPayload();
417	  batchSaving = true;
418	  syncSubmitState();
419	  showBatchReport('<div class="banner busy">正在保存本次批量修改，请勿重复提交…</div>');
420	  try {
421	    const res = await fetch("/api/clients/batch-update", {
422	      method: "POST",
423	      headers: {"Content-Type": "application/json"},
424	      body: JSON.stringify(payload),
425	    });
426	    // 错误回复可能是 {error:"..."}、一段纯文本说明，也可能是空回复；
427	    // 没有可靠结论时一律不能当作明确拒绝或保存成功。
428	    const reply = await readServiceReply(res);
429	    if (!reply) {
430	      // 保存回复无法读取：不知道服务是否已经写入，按无法确认处理。
431	      showBatchReport(unconfirmedBatchHtml("保存回复无法读取（HTTP " + res.status + "）："));
432	      return;
433	    }
434	    const {data, parsed} = reply;
435	
436	    if (!res.ok) {
437	      // 明确拒绝还是无法确认由 classifyFailureReply 统一判定；这里只按批量修改
438	      // 的口径组织提示：明确拒绝说明所有客户资料保持原样并展示原因供修正；
439	      // 无法确认保留已知状态码与可读说明，不断言资料未变或已经回滚。
440	      const failure = classifyFailureReply(res, reply, false);
441	      if (failure.outcome === "rejected") {
442	        showBatchReport('<div class="banner bad">本次修改已全部拒绝，客户资料保持原样。<br>原因：' +
443	          esc(failure.reason) + "</div>");
444	        return;
445	      }
446	      let prefix;
447	      if (failure.status === 400) {
448	        prefix = "保存未成功（HTTP 400），但回复中没有可读的拒绝原因：";
449	      } else if (failure.detail) {
450	        prefix = "保存未成功（HTTP " + failure.status + "）：" + esc(failure.detail) + "。<br>";
451	      } else {
452	        prefix = "保存未成功（HTTP " + failure.status + "），服务没有给出可展示的错误说明：";
453	      }
454	      showBatchReport(unconfirmedBatchHtml(prefix));
455	      return;
456	    }
457	
458	    // 服务明确返回成功：成功处理数量以保存回复为准，不按旧表格、当前勾选或刷新结果重算。
459	    // 只有回复是 JSON 对象、且 updated_count 是非负整数数字时才能确认成功（0 也算）；
460	    // 负数、小数、数字形式的文本、布尔、null 或字段缺失都不是有效处理数量——不转成
461	    // 数字、不取整、不补零；空回复、无法解析或回复不是对象同样无法确认。
462	    const okData = parsed && data && typeof data === "object" && !Array.isArray(data);
463	    const count = okData ? data.updated_count : undefined;
464	    if (!isNonNegativeInt(count)) {
465	      // 成功状态却拿不到有效处理数量：仍不知道修改是否生效，不显示成功数量、
466	      // 不做保存成功后的清理（保留结果处理时页面上的勾选、字段操作与已填内容、
467	      // 旧表格，不触发保存后的列表读取，不自动再次发送修改），按无法确认处理。
468	      const problem = parsed ? "回复中没有有效的处理数量" : "回复内容无法解析";
469	      showBatchReport(unconfirmedBatchHtml("保存请求已返回成功状态，但" + problem + "："));
470	      return;
471	    }
472	    resetBatchForm();
473	    selected.clear();
474	    renderClients();
475	    renderSelection();
476	    let refreshState = "updated";
477	    try {
478	      refreshState = await loadClients();
479	    } catch (loadErr) {
480	      refreshState = "failed";
481	      // 刷新失败不自动重交刚才的修改，也不要求用户再次保存；旧表格（含勾选状态）
482	      // 已按保存成功的结果保留/清除，不被读取失败清空。
483	      showBatchReport(
484	        '<div class="banner ok">已成功处理 <b>' + esc(count) +
485	        "</b> 名客户，勾选已清除，字段编辑已恢复为保持原值。</div>" +
486	        '<div class="banner warn">保存后读取客户列表失败（' + esc(loadErr.message) +
487	        "）：列表暂未更新，当前显示的资料可能仍是保存前的内容；客户资料已按上述结果保存，" +
488	        "稍后重新打开或刷新页面即可看到最新资料，无需再次保存。</div>");
489	    }
490	    if (refreshState === "updated") {
491	      showBatchReport('<div class="banner ok">已成功处理 <b>' + esc(count) +
492	        "</b> 名客户，列表已更新，勾选已清除，字段编辑已恢复为保持原值。</div>");
493	    }
494	    if (refreshState === "stale") {
495	      // 本次保存后的列表读取已被更新的读取取代（例如等待期间又完成了一次导入）：
496	      // 表格与读取提示以最近发起的那次读取为准，这里只确认保存数量，
497	      // 不断言列表已更新，也不误报读取失败。
498	      showBatchReport('<div class="banner ok">已成功处理 <b>' + esc(count) +
499	        "</b> 名客户，勾选已清除，字段编辑已恢复为保持原值。</div>");
500	    }
501	  } catch (err) {
502	    // 连接中断、没拿到任何回复：不知道服务是否已经处理并写入，不能声称资料未变
503	    // 或已经回滚，也不显示成功数量；按无法确认处理，保留当前勾选与填写。
504	    let message = err.message;
505	    if (err instanceof TypeError) message = "无法连接到服务（网络错误）";
506	    showBatchReport(unconfirmedBatchHtml("保存请求未能送达或连接中断（" + esc(message) + "）："));
507	  } finally {
508	    // 等待结束：是否能保存仍取决于有没有选中客户（成功后已清除勾选）。
509	    batchSaving = false;
510	    syncSubmitState();
511	  }
512	});
513	
514	buildBatchFields();
515	
516	document.getElementById("file-input").addEventListener("change", e => {
517	  document.getElementById("filename").textContent = e.target.files[0] ? e.target.files[0].name : "";
518	});
519	
520	function showReport(innerHTML, ok) {
521	  const report = document.getElementById("report");
522	  report.style.display = "block";
523	  report.innerHTML = innerHTML;
524	}
525	
526	// 数量必须是非负整数：缺失、布尔、浮点、负数或 NaN/Infinity 都不算合法数量。
527	function isNonNegativeInt(value) {
528	  return typeof value === "number" && Number.isInteger(value) && value >= 0;
529	}
530	
531	// 只有成功状态下、且报告通过完整校验时才算拿到可靠的导入结果：
532	// 新增/未导入数量为非负整数；未导入明细是数组，逐条含正整数数据记录编号与
533	// 非空文本原因；明细条数与未导入数量一致。任一不满足都返回 null，
534	// 不用 0、空数组或 undefined 补造一份成功报告。
535	function parseImportReport(data) {
536	  if (!data || typeof data !== "object" || Array.isArray(data)) return null;
537	  const importedCount = data.imported_count;
538	  const failedCount = data.failed_count;
539	  if (!isNonNegativeInt(importedCount) || !isNonNegativeInt(failedCount)) return null;
540	  if (!Array.isArray(data.failures) || data.failures.length !== failedCount) return null;
541	  const failures = [];
542	  for (const item of data.failures) {
543	    if (!item || typeof item !== "object") return null;
544	    if (typeof item.row !== "number" || !Number.isInteger(item.row) || item.row <= 0) return null;
545	    if (typeof item.reason !== "string" || !item.reason.trim()) return null;
546	    failures.push({row: item.row, reason: item.reason});
547	  }
548	  return {importedCount, failedCount, failures};
549	}
550	
551	// 记录级失败（重复、字段错误）仍属于成功导入报告：合法的零新增、全部跳过与
552	// 部分新增都按已校验的数量展示，并逐条列出原因，不把记录失败说成整份拒绝。
553	function successReportHtml(report) {
554	  let html = '<div class="banner ok">新增 <b>' + report.importedCount + "</b> 条，" +
555	    "未导入 <b>" + report.failedCount + "</b> 条。</div>";
556	  if (report.failures.length) {
557	    html += '<div class="failures"><p><b>未导入记录（编号按原文件数据记录，表头不计入）：</b></p><ul>';
558	    html += report.failures.map(f =>
559	      "<li>第 <b>" + esc(f.row) + "</b> 条：" + esc(f.reason) + "</li>").join("");
560	    html += "</ul></div>";
561	  }
562	  return html;
563	}
564	
565	// 成功状态之外的统一口径：没有取得可靠结果，不显示任何成功数量或零新增，
566	// 也不断言资料一定未变化、已经回滚或整份文件已拒绝；保留已知的 HTTP 状态码，
567	// 提示先核对客户列表，不自动补交文件。已选文件与当前客户表格保留，
568	// 这一分支不触发导入后的列表读取。
569	function unreliableReportHtml(prefix) {
570	  return '<div class="banner bad">' + prefix +
571	    "没有取得可靠的导入结果，无法确认本次是否新增了客户，客户资料可能已经改变；" +
572	    "请先核对客户列表，再决定是否重新导入。已选文件与当前客户列表均已保留，" +
573	    "不会清空客户、不会自动重新提交。</div>";
574	}
575	
576	document.getElementById("import-form").addEventListener("submit", async e => {
577	  e.preventDefault();
578	  const input = document.getElementById("file-input");
579	  // 等待结果期间再次提交（重复点击、回车触发的表单提交等）一律忽略：
580	  // 不增加请求、不提前解除等待，也不把「正在导入」换成成功、失败或未选文件
581	  // 的提示。等待期间更换/取消文件选择不影响这一判断：本次请求固化在提交时
582	  // 读取到的那份文件上，后来的选择既不被自动补交，也不会改变正在进行的请求。
583	  if (importing) return;
584	  const file = input.files[0];
585	  if (!file) {
586	    showReport('<div class="banner bad">请先选择 CSV 文件。</div>');
587	    return;
588	  }
589	  // 以本次提交时选中的文件为准，固化请求内容；等待期间另选或取消选择都不
590	  // 影响本次请求，回复也只说明这份文件的结果。
591	  const submittedFile = file;
592	  importing = true;
593	  syncImportState();
594	  showReport('<div class="banner busy">正在导入，请勿重复提交…</div>');
595	  try {
596	    let res;
597	    try {
598	      res = await fetch("/api/clients/import", {method: "POST", body: submittedFile});
599	    } catch (netErr) {
600	      // 请求未拿到任何回复：不知道服务是否处理过文件，不能声称资料未变。
601	      showReport(unreliableReportHtml("导入请求失败（" + esc(netErr.message) + "）："));
602	      return;
603	    }
604	
605	    // 错误回复可能是 {error:"..."}、一段纯文本说明，也可能是空回复。
606	    // 回复读取失败时不知道服务是否已写入，按无法确认处理。
607	    const reply = await readServiceReply(res);
608	    if (!reply) {
609	      showReport(unreliableReportHtml("导入回复无法读取（HTTP " + res.status + "）："));
610	      return;
611	    }
612	    const {data, parsed} = reply;
613	
614	    if (!res.ok) {
615	      // 明确拒绝还是无法确认由 classifyFailureReply 统一判定；这里只按 CSV 导入
616	      // 的口径组织提示：明确拒绝说明本次没有新增客户、原有资料保持原样并展示
617	      // 原因供修正；无法确认保留已知状态码与可读说明，不展示原始 JSON，
618	      // 不显示新增数量或零新增，也不声称已经回滚或整份文件已拒绝。
619	      const failure = classifyFailureReply(res, reply, true);
620	      if (failure.outcome === "rejected") {
621	        showReport('<div class="banner bad">整份文件已拒绝导入，本次没有新增客户，原有客户资料保持原样。<br>原因：' +
622	          esc(failure.reason) + "</div>");
623	        return;
624	      }
625	      let prefix;
626	      if (failure.status === 400) {
627	        prefix = "导入未成功（HTTP 400），但回复中没有可靠的拒绝原因：";
628	      } else if (failure.detail) {
629	        prefix = "导入未成功（HTTP " + failure.status + "）：" + esc(failure.detail) + "。";
630	      } else {
631	        prefix = "导入未成功（HTTP " + failure.status + "），服务没有给出可展示的错误说明：";
632	      }
633	      showReport(unreliableReportHtml(prefix));
634	      return;
635	    }
636	
637	    // 成功状态：只有报告完整可校验时才显示新增/未导入数量与逐条原因。
638	    const report = parseImportReport(data);
639	    if (!report) {
640	      const problem = parsed
641	        ? "导入报告不完整，或数量、未导入明细不符合约定"
642	        : "回复内容无法解析";
643	      showReport('<div class="banner bad">导入请求已返回成功状态，但' + problem +
644	        "：本次导入是否生效、新增了多少客户均无法确认，不能按零新增或空明细补算成功结果；" +
645	        "请先核对客户列表，再决定是否重新导入。已选文件保留，不会自动重新提交。</div>");
646	      return;
647	    }
648	
649	    showReport(successReportHtml(report));
650	    // 成功结论只以已校验的报告为准：随后列表读取失败只附加提示，
651	    // 保留已确认的数量、逐条原因与原有表格，不把导入改说成失败。
652	    // 若本次读取已被更新的列表读取取代（stale），表格与读取提示以最近
653	    // 发起的那次为准，这里不再附加任何读取提示，已确认的报告同样不变。
654	    try {
655	      await loadClients();
656	    } catch (loadErr) {
657	      showReport(
658	        document.getElementById("report").innerHTML +
659	        '<div class="banner warn">导入后读取客户列表失败（' + esc(loadErr.message) +
660	        "）：列表暂未更新，当前显示的资料可能不是最新内容；导入结果以上述报告为准，" +
661	        "稍后刷新页面即可，无需重新导入。</div>");
662	    }
663	  } catch (err) {
664	    showReport(unreliableReportHtml("导入处理出现意外问题（" + esc(err.message) + "）："));
665	  } finally {
666	    // 无论结果如何都结束导入等待：按钮恢复为「导入」并可用。不清空、不恢复
667	    // 文件选择——保留用户当时的状态（期间另选的文件或取消后的未选状态），
668	    // 是否能再次导入由下一次主动提交时是否选中文件决定，等待限制不会延续。
669	    importing = false;
670	    syncImportState();
671	  }
672	});
673	
674	// 首次读取失败时页内已显示读取失败提示且表格保持空白/原状，这里吞掉拒绝即可，
675	// 不使用弹窗、不清空任何已有内容。
676	loadClients().catch(() => {});
677	</script>
678	</body>
679	</html>

