// 客户编号最大可到 9223372036854775807（2^63-1），超出 JS 安全整数范围：
// 直接 JSON.parse 会把 9007199254740993 之类的大编号舍入成相近的偶数，
// 两个不同客户会显示成同一编号。这里在解析前把超出安全范围的整数字面量
// 原样包成字符串（跳过字符串内容，只处理结构中的数字），解析后编号一律
// 以精确十进制文本保存与比较；发送批量修改时再原样拼回 JSON 整数，
// 接口的编号仍是 JSON 整数，不做文本化改动。
function quoteUnsafeIntTokens(jsonText) {
  let out = "";
  let i = 0;
  const n = jsonText.length;
  let inString = false;
  while (i < n) {
    const c = jsonText[i];
    if (inString) {
      out += c;
      if (c === "\\" && i + 1 < n) {
        out += jsonText[i + 1];
        i += 2;
        continue;
      }
      if (c === '"') inString = false;
      i += 1;
      continue;
    }
    if (c === '"') {
      inString = true;
      out += c;
      i += 1;
      continue;
    }
    if (c === "-" || (c >= "0" && c <= "9")) {
      let j = i + 1;
      while (j < n && /[0-9.eE+-]/.test(jsonText[j])) j += 1;
      const token = jsonText.slice(i, j);
      // 只处理纯整数字面量；超出安全整数范围的包成字符串，保留原始数字。
      if (/^-?\d+$/.test(token) && !Number.isSafeInteger(Number(token))) {
        out += '"' + token + '"';
      } else {
        out += token;
      }
      i = j;
      continue;
    }
    out += c;
    i += 1;
  }
  return out;
}
```

Note: Number.isSafeInteger(Number("9223372036854775807")) → Number is 9.223372036854776e18 → not safe → quoted. Good. Number("9007199254740991") = 2^53-1 → safe → kept as number → String() later gives exact. Good.

