1	#!/usr/bin/env node
2	/**
3	 * 首页批量保存结果处理的页面层面回归保障。
4	 *
5	 * 启动真实 app.py 服务（与 smoke_test.py 同一后端，不模拟、不改动接口公开行为），
6	 * 用 Puppeteer 驱动系统 Chrome 打开首页，通过请求拦截分别「破坏」保存成功之后
7	 * 的那次客户列表读取，逐项验证：
8	 *
9	 * 1. 保存已确认成功、但随后客户列表读取失败：
10	 *      - 连接失败 / HTTP 非成功状态 / 响应无法解析 / 响应缺少 clients 数组
11	 *    页面仍明确显示「已成功处理 N 名客户」；成功数量以保存回复 updated_count
12	 *    为准，不按刷新后出现的记录数重算；同时提示列表暂未更新、当前资料可能仍是
13	 *    保存前内容、稍后刷新即可查看、无需再次保存；
14	 * 2. 保存确认成功后，无论列表是否读到：勾选清除、已选归零，来源/地区/行业/重要
15	 *    日期恢复「保持原值」，输入清空并回到不可填写状态；
16	 * 3. 列表读取失败时旧表格内容（编号、名称、各字段）保留，不清表、不显示
17	 *    「还没有客户记录」；结束保存等待、按钮恢复且无勾选时不可提交；不重发修改；
18	 * 4. 随后刷新/重新打开页面读取成功：显示真实资料、撤下读取失败提示；
19	 *    真实空列表正常显示空列表提示，不被当成读取失败；
20	 * 5. 保存成功且列表读取成功：显示处理数量、更新相关列、完成同样的勾选与编辑清理；
21	 * 6. 保存接口明确拒绝（HTTP 400 具体原因）：保留勾选、字段操作与已填内容供修正，
22	 *    不套用保存成功后的清理与提示；
23	 * 7. 保存请求尚未返回的等待期间：按钮保持「正在保存…」不可提交，选中信息、字段
24	 *    操作与填写保留且不显示成功数量；重复提交（含回车触发的表单提交）不发出第二
25	 *    个请求、等待提示不被替换成成功或未选客户错误；期间可正常改选客户、调整字段
26	 *    与输入，但不解除等待状态（含先取消全部再重选）；已发出请求的勾选与内容以第
27	 *    一次保存为准，结果返回后不自动补交等待期间的改动；
28	 * 8. 等待期间改动后服务明确 400 拒绝：保留的是返回结果时页面上的勾选、字段操作
29	 *    与填写；等待结束后有选中客户才能再次保存，没有勾选则按钮保持不可提交。
30	 */
31	import {spawn} from "node:child_process";
32	import {dirname, join} from "node:path";
33	import {fileURLToPath} from "node:url";
34	import {mkdtempSync, rmSync} from "node:fs";
35	import {tmpdir} from "node:os";
36	import puppeteer from "puppeteer";
37	
38	const HERE = dirname(fileURLToPath(import.meta.url));
39	const APP = join(HERE, "app.py");
40	const TMP = mkdtempSync(join(tmpdir(), "clientbook-page-"));
41	const FAILURES = [];
42	let checkCount = 0;
43	
44	function check(label, cond, detail = "") {
45	  checkCount += 1;
46	  if (cond) {
47	    console.log("PASS", label);
48	  } else {
49	    FAILURES.push({label, detail: typeof detail === "string" ? detail : JSON.stringify(detail)});
50	    console.log("FAIL", label, typeof detail === "string" ? detail : JSON.stringify(detail));
51	  }
52	}
53	
54	// ---------------------------------------------------------------------------
55	// 真实 app.py 进程
56	// ---------------------------------------------------------------------------
57	function startApp(label) {
58	  const proc = spawn("python3", [
59	    APP, "serve", "--host", "127.0.0.1", "--port", "0",
60	    "--data-dir", join(TMP, label),
61	  ], {cwd: HERE, stdio: ["ignore", "pipe", "pipe"]});
62	  const port = new Promise((resolve, reject) => {
63	    let buf = "";
64	    const onData = d => {
65	      buf += d.toString();
66	      const m = buf.match(/http:\/\/127\.0\.0\.1:(\d+)/);
67	      if (m) {
68	        proc.stdout.off("data", onData);
69	        resolve(Number(m[1]));
70	      }
71	    };
72	    proc.stdout.on("data", onData);
73	    proc.on("exit", code => reject(new Error(`app.py 意外退出（${code}）：${buf}`)));
74	  });
75	  return {proc, port};
76	}
77	
78	async function waitReady(base, deadlineMs = 8000) {
79	  const deadline = Date.now() + deadlineMs;
80	  while (Date.now() < deadline) {
81	    try {
82	      const res = await fetch(base + "/health");
83	      if (res.status === 200) return;
84	    } catch { /* 尚未就绪 */ }
85	    await new Promise(r => setTimeout(r, 100));
86	  }
87	  throw new Error("服务未在限定时间内就绪：" + base);
88	}
89	
90	async function stopApp(ctx) {
91	  ctx.proc.kill(); // SIGTERM：app.py 收到后走正常关闭
92	  const timer = setTimeout(() => {
93	    try { ctx.proc.kill("SIGKILL"); } catch { /* 已退出 */ }
94	  }, 2000);
95	  await new Promise(r => ctx.proc.on("exit", r));
96	  clearTimeout(timer);
97	}
